import React, { useState, useRef } from 'react';
import { motion, AnimatePresence } from "framer-motion";
import './App.css';

// ӘР ДЕҢГЕЙГЕ АРНАЛҒАН 5 СҰРАҚТАН ТҰРАТЫН БАЗА
const QUESTIONS_DATABASE = {
  1: [
    { q: "«Ескендір» поэмасының авторы кім?", a: ["Абай", "Шәкәрім", "Мағжан", "Мұхтар"], c: 0 },
    { q: "Ескендірдің ұстазы кім?", a: ["Сократ", "Платон", "Аристотель", "Әл-Фараби"], c: 2 },
    { q: "Ескендір қай елдің патшасы?", a: ["Рим", "Македония", "Парсы", "Египет"], c: 1 },
    { q: "Поэмадағы басты кейіпкердің бірі?", a: ["Ахиллес", "Ескендір", "Гектор", "Цезарь"], c: 1 },
    { q: "Абай бұл поэманы қай жылы жазды?", a: ["1880", "1900", "1895", "1890"], c: 2 }
  ],
  // Қалған деңгейлерге де осылай 5 сұрақтан қосуға болады
};

const INITIAL_POINTS = [
  { "id": 1, "x": 59.06, "y": 45.66, "s": 0.9 }, { "id": 2, "x": 48.66, "y": 70.97, "s": 1 },
  { "id": 3, "x": 46.26, "y": 54.51, "s": 0.85 }, { "id": 4, "x": 64.40, "y": 50.79, "s": 0.85 },
  { "id": 5, "x": 44.66, "y": 50.71, "s": 0.9 }, { "id": 6, "x": 55.59, "y": 39.73, "s": 0.85 },
  { "id": 7, "x": 57.20, "y": 30.71, "s": 0.85 }, { "id": 8, "x": 50.80, "y": 22.30, "s": 0.85 },
  { "id": 9, "x": 46.53, "y": 14.16, "s": 0.6 },
  { "id": 10, "x": 51.33, "y": 7.61, "s": 0.8, "type": "finish_label" }
];

const EDIT_MODE = true;

function App() {
  const [gameState, setGameState] = useState('start');
  const [points, setPoints] = useState(INITIAL_POINTS);
  const [unlockedLevel, setUnlockedLevel] = useState(1);
  const [activeLvl, setActiveLvl] = useState(null);
  const [currentQIndex, setCurrentQIndex] = useState(0);
  const [selectedAns, setSelectedAns] = useState(null);
  const [feedback, setFeedback] = useState(null);
  const mapAreaRef = useRef(null);

  const copyData = () => {
    const data = {
      width: 608, height: 1832,
      points: points
    };
    navigator.clipboard.writeText(JSON.stringify(data, null, 2)).then(() => alert("Деректер көшірілді!"));
  };

  const updatePos = (id, info) => {
    if (!EDIT_MODE || !mapAreaRef.current) return;
    const rect = mapAreaRef.current.getBoundingClientRect();
    const x = ((info.point.x - rect.left) / rect.width) * 100;
    const y = ((info.point.y - rect.top) / rect.height) * 100;
    setPoints(pts => pts.map(p => p.id === id ? { ...p, x, y } : p));
  };

  const handleAnswer = (idx) => {
    if (feedback) return;
    const questions = QUESTIONS_DATABASE[1]; // Әзірге 1-деңгей сұрақтарын қолданамыз
    const correct = questions[currentQIndex].c;
    setSelectedAns(idx);

    if (idx === correct) {
      setFeedback('correct');
      setTimeout(() => {
        if (currentQIndex < questions.length - 1) {
          setCurrentQIndex(prev => prev + 1);
          setFeedback(null); setSelectedAns(null);
        } else {
          setUnlockedLevel(prev => Math.max(prev, activeLvl + 1));
          setActiveLvl(null); setFeedback(null); setSelectedAns(null); setCurrentQIndex(0);
        }
      }, 600);
    } else {
      setFeedback('wrong');
    }
  };

  return (
    <div className="game-wrapper">
      <AnimatePresence>
        {gameState === 'start' && (
          <motion.div className="start-screen" exit={{ opacity: 0 }}>
            <h1 className="main-title">ЕСКЕНДІР</h1>
            <button className="start-btn" onClick={() => setGameState('map')}>ОЙНАУ</button>
          </motion.div>
        )}

        {gameState === 'map' && (
          <motion.div className="map-container" initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
            <div className="ui-overlay">
              <button onClick={() => setGameState('start')}>МӘЗІР</button>
              {EDIT_MODE && <button className="save-btn" onClick={copyData}>📍 САҚТАУ</button>}
            </div>

            <motion.div className="map-scroll-area" drag="y" dragConstraints={{ top: -1224, bottom: 0 }}>
              <div ref={mapAreaRef} className="map-content">
                <img src={process.env.PUBLIC_URL + "/img.jpg"} alt="Map" className="map-img" />
                {points.map((p) => {
                  const isLocked = p.id > unlockedLevel;
                  const isFinish = p.type === 'finish_label';
                  return (
                    <motion.div key={p.id} drag={EDIT_MODE} onDrag={(e, info) => updatePos(p.id, info)}
                      className="node" style={{ left: `${p.x}%`, top: `${p.y}%`, scale: p.s, position: 'absolute' }}>
                      {isFinish ? <div className="finish-banner">FINISH</div> :
                        <div className="coin-perspective" onClick={() => !isLocked && setActiveLvl(p.id)}>
                          <div className={`coin ${isLocked ? 'silver' : 'gold'}`}>{isLocked ? "🔒" : p.id}</div>
                        </div>}
                    </motion.div>
                  );
                })}
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {activeLvl && (
        <div className="quiz-overlay">
          <div className="quiz-card">
            <div className="quiz-header">
              <span className="q-count">Сұрақ {currentQIndex + 1}/5</span>
              <button className="close-btn" onClick={() => setActiveLvl(null)}>✕</button>
            </div>
            <h2 className="q-text">{QUESTIONS_DATABASE[1][currentQIndex].q}</h2>
            <div className="ans-grid">
              {QUESTIONS_DATABASE[1][currentQIndex].a.map((ans, i) => (
                <button key={i} className={`ans-opt ${selectedAns === i ? feedback : ''}`} onClick={() => handleAnswer(i)}>{ans}</button>
              ))}
            </div>
            {feedback === 'wrong' && (
              <div className="error-box">
                <p>Қате! Қайта көріңіз.</p>
                <button className="btn-retry" onClick={() => {setFeedback(null); setSelectedAns(null);}}>ҚАЙТАЛАУ</button>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}
export default App;